using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult result)
        {
            if (EditorApplication.isPlaying)
                throw new System.Exception("Stop Play first");
            var s = EditorSceneManager.OpenScene("Assets/CampusSim/Scenes/CampusTerrain.unity");
            foreach (var root in s.GetRootGameObjects())
                foreach (var t in root.GetComponentsInChildren<Transform>(true))
                    if (t.name == "01 Terrain, water and vegetation")
                        foreach (Transform child in t)
                            result.Log(child.name + " children=" + child.childCount);
        }
    }
}
